  // FIXME: this regex looks a bit broken
  var regex = /^(https?):\/\/([^:&^\/]*)\:?(\d*)(.*)$/g;
  regex.lastIndex = 0;
  var m = regex.exec(str);
  var url = (m === null) ? null : {
    full: str,
    scheme: m[1],
    host: m[2],
    port: m[3],
    path: m[4]
  };
};

